-- Uniform DB facade for integration tests.---- The dialect under test is selected by env LUA_SQLBUILDER_DB-- (default "sqlite"); credentials for mysql/postgres come from env,-- matching the GitHub Actions services (see .github/workflows/ci.yml).----   db.current()            → "sqlite" | "mysql" | "postgres"--   db.connect()            → conn | nil, reason   (nil when driver missing)--   conn:exec(sql, ...)     → true | nil, err       (bound params if supported)--   conn:query(sql, ...)    → rows | nil, err       (rows = array of {col=val})--   conn:last_insert_id()   → number | nil--   conn.supports_params    → true when the driver can bind ? parameters--   conn:close()---- Driver note: LuaSQL (mysql/postgres) has NO parameter binding in the-- released 2.x line, so param-bound execution is provided by lsqlite3 and-- pgmoon only; mysql integration exercises to_sql (inline) execution and-- string-level prepare validation (see spec/audit).local db = {}local unpack = table.unpack or unpack -- luacheck: ignore 143local env = function(name, default) return os.getenv(name) or default enddb.current = function()  return env("LUA_SQLBUILDER_DB", "sqlite")end-- Options table to bind builders to the dialect under test:--   local SQLBuilder = require "lua_SQLBuilder"--   SELECT("*", db.opts())db.opts = function()  return { dialect = db.current() }end-- Normalize a driver value for portable assertions.local function normalize_value(v)  if type(v) == "string" then    local n = tonumber(v)    if n and tostring(n) == v then      return n    end  end  return vend-- Inline SQL literal for fixture seeding (values are trusted constants).local function literal(v)  if v == nil then    return "NULL"  end  local t = type(v)  if t == "number" then    return tostring(v)  end  if t == "boolean" then    return v and "1" or "0"  end  return "'" .. tostring(v):gsub("'", "''") .. "'"enddb.literal = literal--------------------------------------------------------------------------------- SQLite (lsqlite3) — supports ? binding-------------------------------------------------------------------------------local function connect_sqlite()  local ok, lsqlite3 = pcall(require, "lsqlite3")  if not ok then    return nil, "lsqlite3 not available"  end  local handle = lsqlite3.open_memory()  if not handle then    return nil, "lsqlite3 failed to open database"  end  local conn = {    dialect = "sqlite",    supports_params = true,    _db = handle,  }  function conn:exec(sql, ...)    local n = select("#", ...)    if n == 0 then      local code, errmsg = self._db:exec(sql)      if code ~= 0 then        return nil, errmsg or tostring(code)      end      return true    end    -- Bound path, defensively: lsqlite3 versions differ on raise vs return.    local ok_p, stmt, prep_err = pcall(self._db.prepare, self._db, sql)    if not ok_p or not stmt then      return nil, "prepare failed (" .. tostring(prep_err) .. "): " .. tostring(sql)    end    local args = { ... }    local ok_b, bind_err = pcall(stmt.bind_values, stmt, unpack(args))    if not ok_b then      stmt:finalize()      return nil, "bind failed: " .. tostring(bind_err)    end    if bind_err ~= nil and bind_err ~= 0 then      stmt:finalize()      return nil, "bind returned " .. tostring(bind_err)    end    local ok_s, step = pcall(stmt.step, stmt)    if not ok_s then      stmt:finalize()      return nil, "step raised: " .. tostring(step)    end    stmt:finalize()    if step == lsqlite3.DONE or step == lsqlite3.ROW then      return true    end    return nil, "step returned " .. tostring(step)  end  function conn:query(sql, ...)    -- nrows returns (iterator, state, control) for the generic for; wrap the    -- whole loop so the triple survives and failures carry the SQL.    local args = { ... }    local rows = {}    local ok_iter, iter_err = pcall(function()      for row in self._db.nrows(self._db, sql, unpack(args)) do        local normalized = {}        for k, v in pairs(row) do          normalized[k] = normalize_value(v)        end        rows[#rows + 1] = normalized      end    end)    if not ok_iter then      return nil, "query failed (" .. tostring(iter_err) .. "): " .. tostring(sql)    end    return rows  end  function conn:last_insert_id()    return self._db:last_insert_rowid()  end  function conn:close()    self._db:close()  end  return connend--------------------------------------------------------------------------------- PostgreSQL (pgmoon) — pure Lua, supports ? binding (converted to $n)-------------------------------------------------------------------------------local function connect_pgmoon()  local ok, pgmoon = pcall(require, "pgmoon")  if not ok then    return nil, "pgmoon not available"  end  local pg = pgmoon.new({    host = env("POSTGRES_HOST", "127.0.0.1"),    port = tonumber(env("POSTGRES_PORT", "5432")),    user = env("POSTGRES_USER", "postgres"),    password = env("POSTGRES_PASSWORD", "postgres"),    database = env("POSTGRES_DATABASE", "sqlbuilder_test"),  })  local connected, conn_err = pg:connect()  if not connected then    return nil, "connection failed: " .. tostring(conn_err)  end  local conn = {    dialect = "postgres",    supports_params = true,    _pg = pg,  }  -- PostgreSQL prepared statements use $n placeholders. pgmoon does not  -- convert "?", so translate positionally (when params are present every  -- "?" in the SQL is a placeholder; inline string literals with "?" never  -- reach this path with params).  local function pg_convert(sql, n)    local i = 0    local out = sql:gsub("%?", function()      i = i + 1      return "$" .. i    end)    if i ~= n then      return nil, "placeholder count mismatch: " .. i .. " placeholders, " .. n .. " params"    end    return out  end  function conn:exec(sql, ...)    local n = select("#", ...)    if n > 0 then      local converted, convert_err = pg_convert(sql, n)      if not converted then        return nil, convert_err      end      sql = converted    end    local res, err = self._pg:query(sql, ...)    if not res then      return nil, err    end    return true  end  function conn:query(sql, ...)    local n = select("#", ...)    if n > 0 then      local converted, convert_err = pg_convert(sql, n)      if not converted then        return nil, convert_err      end      sql = converted    end    local res, err = self._pg:query(sql, ...)    if not res then      return nil, err    end    local rows = {}    for _, row in ipairs(res) do      local normalized = {}      for k, v in pairs(row) do        normalized[k] = normalize_value(v)      end      rows[#rows + 1] = normalized    end    return rows  end  function conn:last_insert_id()    local ok_rows, rows = pcall(self.query, self, "SELECT LASTVAL() AS id")    if ok_rows and rows and rows[1] then      return rows[1].id    end    return nil  end  function conn:close()    self._pg:close()  end  return connend-- Generic LuaSQL connection (mysql/duckdb/oracle): inline execution only,-- LuaSQL 2.x has no ? binding; fetch mode 'a' returns named rows.local function luas_driver_or(mod)  return (mod.mysql or mod.duckdb or mod.oci8) and    (mod.mysql or mod.duckdb or mod.oci8)() or modendlocal function make_luasql_conn(dialect, handle, env_obj)  local conn = {    dialect = dialect,    supports_params = false,    _conn = handle,    _env = env_obj,  }  function conn:exec(sql, ...)    local n = select("#", ...)    if n > 0 then      return nil, dialect .. " driver (LuaSQL 2.x) does not support bound parameters"    end    local cursor, err = self._conn:execute(sql)    if not cursor then      return nil, err    end    if type(cursor) == "table" and cursor.close then      cursor:close()    end    return true  end  function conn:query(sql)    local cursor, query_err = self._conn:execute(sql)    if not cursor then      return nil, query_err    end    local rows = {}    while true do      local raw = cursor:fetch({}, "a")      if not raw then break end      local normalized = {}      for k, v in pairs(raw) do        if v ~= nil then          normalized[k] = normalize_value(v)        end      end      rows[#rows + 1] = normalized    end    cursor:close()    return rows  end  function conn:last_insert_id()    local ok_li, id = pcall(self._conn.getlastautoid, self._conn)    if ok_li and id then      return id    end    return nil  end  function conn:close()    self._conn:close()    self._env:close()  end  return connendlocal function connect_luasql_mysql()  local ok, luasql_driver = pcall(require, "luasql.mysql")  if not ok then    return nil, "luasql.mysql not available"  end  local env_obj = luas_driver_or(luasql_driver)  local host = env("MYSQL_HOST", "127.0.0.1")  local port = env("MYSQL_PORT", "3306")  local user = env("MYSQL_USER", "root")  local password = env("MYSQL_PASSWORD", "root")  local database = env("MYSQL_DATABASE", "sqlbuilder_test")  local handle, connect_err = env_obj:connect(database, user, password, host, port)  if not handle then    env_obj:close()    return nil, "connection failed: " .. tostring(connect_err)  end  return make_luasql_conn("mysql", handle, env_obj)endlocal function connect_luasql_duckdb()  local ok, luasql_driver = pcall(require, "luasql.duckdb")  if not ok then    return nil, "luasql.duckdb not available"  end  local env_obj = luas_driver_or(luasql_driver)  local handle, connect_err = env_obj:connect(":memory:")  if not handle then    env_obj:close()    return nil, "duckdb open failed: " .. tostring(connect_err)  end  return make_luasql_conn("duckdb", handle, env_obj)endlocal function connect_luasql_oci8()  local ok, luasql_driver = pcall(require, "luasql.oci8")  if not ok then    return nil, "luasql.oci8 not available"  end  local env_obj = luas_driver_or(luasql_driver)  local user = env("ORACLE_USER", "app")  local password = env("ORACLE_PASSWORD", "app")  local host = env("ORACLE_HOST", "127.0.0.1")  local port = env("ORACLE_PORT", "1521")  local service = env("ORACLE_SERVICE", "FREEPDB1")  -- EZCONNECT: host:port/service  local handle, connect_err = env_obj:connect(fmt("%s:%s/%s", host, port, service), user, password)  if not handle then    env_obj:close()    return nil, "connection failed: " .. tostring(connect_err)  end  return make_luasql_conn("oracle", handle, env_obj)end--------------------------------------------------------------------------------- ClickHouse (HTTP interface via luasocket) — inline execution only-------------------------------------------------------------------------------local function connect_clickhouse()  local ok_http, http = pcall(require, "socket.http")  local ok_ltn12, ltn12 = pcall(require, "ltn12")  local ok_cjson, cjson = pcall(require, "cjson")  if not (ok_http and ok_ltn12 and ok_cjson) then    return nil, "clickhouse HTTP needs luasocket + cjson"  end  local host = env("CLICKHOUSE_HOST", "127.0.0.1")  local port = env("CLICKHOUSE_PORT", "8123")  local url = fmt("http://%s:%s/", host, port)  local conn = {    dialect = "clickhouse",    supports_params = false,    _url = url,    _http = http,    _ltn12 = ltn12,    _cjson = cjson,  }  -- POST a raw query; returns body string or nil, err.  local function post(self, sql)    local resp = {}    local code, _, headers = self._http.request{      url = self._url,      method = "POST",      source = self._ltn12.source.string(sql),      sink = self._ltn12.sink.table(resp),      headers = { ["Content-Type"] = "application/x-www-form-urlencoded" },    }    local body = table.concat(resp)    if code ~= 200 then      -- ClickHouse returns errors in the body with a non-200 status      return nil, "clickhouse HTTP " .. tostring(code) .. ": " .. (body or "")    end    return body  end  function conn:exec(sql, ...)    local n = select("#", ...)    if n > 0 then      return nil, "clickhouse driver does not support ? binding (use to_sql)"    end    local _, err = post(self, sql)    if err then      return nil, err    end    return true  end  function conn:query(sql)    -- append JSONEachRow for SELECTs (exec never reaches here)    local body, err = post(self, sql .. " FORMAT JSONEachRow")    if err then      return nil, err    end    if body == nil or body == "" then      return {}    end    local rows = {}    for line in body:gmatch("[^\n]+") do      local ok_decode, row = pcall(self._cjson.decode, self._cjson, line)      if not ok_decode then        return nil, "clickhouse JSON parse failed: " .. tostring(row)      end      local normalized = {}      for k, v in pairs(row) do        if v ~= self._cjson.null then          normalized[k] = normalize_value(v)        end      end      rows[#rows + 1] = normalized    end    return rows  end  function conn:close() end -- HTTP is stateless  return connend-------------------------------------------------------------------------------local connections = {}-- Connect (cached per dialect) or return nil, reason when the driver or-- server is unavailable so specs can `pending()` gracefully.function db.connect()  local dialect = db.current()  if connections[dialect] then    return connections[dialect]  end  local conn, reason  if dialect == "sqlite" then    conn, reason = connect_sqlite()  elseif dialect == "mysql" then    conn, reason = connect_luasql_mysql()  elseif dialect == "postgres" then    conn, reason = connect_pgmoon()  elseif dialect == "duckdb" then    conn, reason = connect_luasql_duckdb()  elseif dialect == "clickhouse" then    conn, reason = connect_clickhouse()  elseif dialect == "oracle" then    conn, reason = connect_luasql_oci8()  else    return nil, "unknown dialect: " .. dialect  end  if conn then    connections[dialect] = conn  end  return conn, reasonendfunction db.close_all()  for _, conn in pairs(connections) do    pcall(conn.close, conn)  end  connections = {}endreturn db